import{_ as t,c as r,o as a,a5 as n}from"./chunks/framework.DYgWcJ6Z.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"manual/introduction.md","filePath":"manual/introduction.md","lastUpdated":1754997662000}'),i={name:"manual/introduction.md"};function o(s,e,l,d,p,c){return a(),r("div",null,e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>JSAR</strong> (<a href="https://ipa-reader.xyz/?text=d%CA%92:-sar" target="_blank" rel="noreferrer">/dʒ:-sar/</a>) is a Web browser engine designed for the spatial Web. It enables you to create and present immersive Web contents using the modern Web technologies (<a href="https://html.spec.whatwg.org/multipage/" target="_blank" rel="noreferrer">HTML5</a>, <a href="https://www.w3.org/TR/css-2023/" target="_blank" rel="noreferrer">CSS3</a>, <a href="https://www.typescriptlang.org/" target="_blank" rel="noreferrer">TypeScript</a>) and seamlessly integrate them into mainstream 3D engines like <a href="https://unity.com/" target="_blank" rel="noreferrer">Unity</a>, <a href="https://www.unrealengine.com/" target="_blank" rel="noreferrer">UnrealEngine</a>, and other 3D engines.</p><blockquote><p><strong>📖 Learn More</strong>: For a comprehensive understanding of the architectural decisions behind JSAR and how it differs from traditional browsers, read our technical article: <a href="/runtime/blogs/spatial-browser-engine.html">Understanding the Spatial Web Browser Engine</a>.</p></blockquote><h2 id="spatial-web" tabindex="-1">Spatial Web <a class="header-anchor" href="#spatial-web" aria-label="Permalink to &quot;Spatial Web&quot;">​</a></h2><p>The Spatial Web represents the next evolution of the Web, where every HTML element exists in three-dimensional space with real 3D coordinates, rather than being confined to flat 2D screens. This spatial transformation enables developers to freely leverage Web technologies to create truly immersive experiences, seamlessly blending virtual reality (VR), augmented reality (AR), and mixed reality (MR) into both our physical world and any digital virtual environments.</p><p>Key characteristics of the Spatial Web include:</p><ul><li><strong>3D-First Design</strong>: Content and interfaces are designed to exist in 3D space</li><li><strong>Natural Interaction</strong>: Users can interact with digital content using natural gestures and movements</li><li><strong>Contextual Awareness</strong>: Digital experiences that understand and respond to their physical surroundings</li><li><strong>Persistent</strong>: Digital content can remain anchored in physical space across sessions</li></ul><blockquote><p><strong>📚 Deep Dive</strong>: To understand why JSAR was built from scratch as a spatial browser engine rather than extending traditional browsers, explore our detailed analysis in <a href="/runtime/blogs/spatial-browser-engine.html">Understanding the Spatial Web Browser Engine</a>.</p></blockquote><h3 id="spatial-web-on-desktop" tabindex="-1">Spatial Web on Desktop <a class="header-anchor" href="#spatial-web-on-desktop" aria-label="Permalink to &quot;Spatial Web on Desktop&quot;">​</a></h3><p>The Spatial Web is not limited to XR devices - it&#39;s also transforming how we interact with content on traditional desktop computers. On desktop platforms, Spatial Web browsing creates a bridge between 2D and 3D experiences by:</p><ul><li><strong>Depth-Based Navigation</strong>: Instead of traditional tab-based browsing, content can be organized in 3D space with depth, allowing users to navigate &quot;forward&quot; and &quot;backward&quot; through information layers</li><li><strong>Spatial Organization</strong>: Web content can be arranged in a three-dimensional workspace, enabling more intuitive organization of multiple pages, documents, and applications</li><li><strong>Enhanced Visualization</strong>: Data and content can be presented with depth and dimension, making complex information more comprehensible through spatial relationships</li><li><strong>Natural Interactions</strong>: Even with a mouse and keyboard, users can interact with content in more natural ways by moving through 3D space rather than just clicking through flat pages</li></ul><p>This desktop implementation of Spatial Web maintains the core principles of spatial computing while adapting them to traditional input methods, creating a more immersive and intuitive browsing experience without requiring specialized hardware.</p><h2 id="project-objectives" tabindex="-1">Project Objectives <a class="header-anchor" href="#project-objectives" aria-label="Permalink to &quot;Project Objectives&quot;">​</a></h2><ul><li>Native support for rendering Spatial Web content</li><li>Designed for Web developers, no need to learn new languages or frameworks.</li><li>Ability to render existing Web applications spatially without modifications.</li></ul><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Designed for the spatial Web</strong> - Every HTML element (including 2D &amp; 3D) is spatially rendered in the browser.</li><li><strong>Web Standards Compliant</strong> - Supports modern Web standards, including HTML5, CSS3, DOM, <a href="https://www.khronos.org/webgl/" target="_blank" rel="noreferrer">WebGL</a>, <a href="https://www.w3.org/TR/webxr/" target="_blank" rel="noreferrer">WebXR</a> and others.</li><li><strong>High Performance</strong> - Dynamically batches all spatialized HTML elements into ≤10 GPU draw calls per frame.</li><li><strong>Cross-Platform</strong> - Delivers flawless performance across every platform (desktop, mobile, and XR) with pixel-perfect consistency.</li><li><strong>Web Developer Friendly</strong> - Deep <a href="https://developer.chrome.com/docs/devtools/" target="_blank" rel="noreferrer">Chrome DevTools</a> integration for seamless debugging and profiling.</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><p>Let&#39;s explore how JSAR can benefit different types of developers:</p><h3 id="for-xr-system-developers" tabindex="-1">For XR System Developers <a class="header-anchor" href="#for-xr-system-developers" aria-label="Permalink to &quot;For XR System Developers&quot;">​</a></h3><p>XR system developers are those who build and maintain XR operating systems and platforms, such as <a href="https://about.meta.com/" target="_blank" rel="noreferrer">Meta</a>&#39;s <a href="https://www.meta.com/quest/" target="_blank" rel="noreferrer">Quest OS</a>, <a href="https://www.picoxr.com/" target="_blank" rel="noreferrer">Pico</a>&#39;s operating system, or other mixed reality platforms. If you&#39;re developing these types of XR systems or platforms, JSAR offers:</p><ul><li>True spatial rendering of HTML elements in 3D space, not just flat browser windows</li><li>High-performance HTML rendering optimized for spatial computing with full depth perception</li></ul><p>For example, if you&#39;re working on <a href="https://www.meta.com/quest/" target="_blank" rel="noreferrer">Quest</a> or <a href="https://www.picoxr.com/" target="_blank" rel="noreferrer">Pico</a>&#39;s system-level features, you can use JSAR to:</p><ul><li>Build system UI and menus using familiar Web technologies (HTML/CSS/JavaScript)</li><li>Create immersive web-based system applications</li><li>Build spatial computing experiences that leverage web technologies</li><li>Integrate web content browsers into your XR platform</li></ul><h3 id="for-web-developers-no-3d-xr-experience-required" tabindex="-1">For Web Developers (No 3D/XR Experience Required) <a class="header-anchor" href="#for-web-developers-no-3d-xr-experience-required" aria-label="Permalink to &quot;For Web Developers (No 3D/XR Experience Required)&quot;">​</a></h3><p>If you&#39;re a web developer with traditional HTML/CSS/JavaScript experience:</p><ul><li>Run your existing 2D web applications in spatial environments without modification</li><li>Leverage your current web development skills to create spatial experiences</li><li>Progressive transition to 3D/XR development by only adding CSS properties like <code>transform: translate3d(0, 1, 0)</code></li></ul><h3 id="for-webxr-developers" tabindex="-1">For WebXR Developers <a class="header-anchor" href="#for-webxr-developers" aria-label="Permalink to &quot;For WebXR Developers&quot;">​</a></h3><p>If you&#39;re already working with <a href="https://www.w3.org/TR/webxr/" target="_blank" rel="noreferrer">WebXR</a>:</p><ul><li>Create rich spatial UI components and overlays using standard HTML and CSS</li><li>Seamlessly mix 2D web content with 3D/XR experiences</li><li>Develop cross-platform XR applications with consistent rendering</li></ul><h2 id="documentation-usage-guide" tabindex="-1">Documentation Usage Guide <a class="header-anchor" href="#documentation-usage-guide" aria-label="Permalink to &quot;Documentation Usage Guide&quot;">​</a></h2><p>This documentation is organized to help you quickly find the information you need. Here&#39;s how to effectively use it:</p><h3 id="structure-overview" tabindex="-1">Structure Overview <a class="header-anchor" href="#structure-overview" aria-label="Permalink to &quot;Structure Overview&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>Description</th></tr></thead><tbody><tr><td><strong>Getting Started</strong></td><td>Introduction to JSAR, quick start guide, and basic concepts</td></tr><tr><td><strong>Features</strong></td><td>Comprehensive coverage of modules, TypeScript support, graphics libraries (<a href="https://www.babylonjs.com/" target="_blank" rel="noreferrer">Babylon.js</a>, <a href="https://threejs.org/" target="_blank" rel="noreferrer">Three.js</a>, <a href="http://vanilla-js.com/" target="_blank" rel="noreferrer">VanillaJS</a>), media, and advanced features like <a href="https://webassembly.org/" target="_blank" rel="noreferrer">WebAssembly</a> and <a href="https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API" target="_blank" rel="noreferrer">Web Workers</a></td></tr><tr><td><strong>Integration</strong></td><td>Guides for integrating JSAR with platforms like Unity and other 3D engines via C/C++ embedder APIs</td></tr><tr><td><strong>Developer Tools</strong></td><td>Resources for debugging, preview functionality, and development tools including GUI features and packaging</td></tr><tr><td><strong>Tutorials</strong></td><td>Hands-on examples covering everything from Hello World applications to creating materials, meshes, and handling network requests</td></tr><tr><td><strong>References</strong></td><td>Detailed documentation on APIs and specifications</td></tr></tbody></table><h3 id="writing-style" tabindex="-1">Writing Style <a class="header-anchor" href="#writing-style" aria-label="Permalink to &quot;Writing Style&quot;">​</a></h3><p>Our documentation follows these principles:</p><ul><li><strong>Self-contained sections</strong>: Each section is written to be understood independently</li><li><strong>Progressive disclosure</strong>: Concepts build upon each other naturally</li><li><strong>Practical examples</strong>: Real-world code samples accompany explanations</li><li><strong>Cross-references</strong>: Links to related topics for deeper understanding</li></ul><p>We aim to balance comprehensiveness with clarity, ensuring you can quickly find answers while having access to detailed information when needed.</p>',37)]))}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
